changeSet.sql:
UPDATE sketch s SET canon_variation_id = COALESCE(
    s.placed_from_variation_id,
    (SELECT v.variation_id FROM variation v
     WHERE v.sketch_id = s.sketch_id AND v.ordinal IS NOT NULL AND v.deleted_at IS NULL
     ORDER BY v.ordinal LIMIT 1))
WHERE s.canon_variation_id IN (SELECT variation_id FROM variation WHERE ordinal IS NULL);

UPDATE sketch s SET placed_from_variation_id = s.canon_variation_id
WHERE s.canon_variation_id IS NOT NULL AND s.placed_from_variation_id IS NULL;

DELETE FROM variation WHERE ordinal IS NULL;
